insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('grand-bahama-freeport-bahamas', '11C', 'Grand Bahama / Freeport', 'Bahamas', 'The shark capital of the northern Bahamas', 'live', 'verified', 'oceanAerial', 'Bahamas', '{"diveglobal","liveaboard","expedition","wildlife","family","tropical"}', '{}', '{"premier","ultra"}', null, null, '{"key_facts":["UNEXSO - veteran dive op: reef/wreck/shark + dolphin encounters","Lucayan National Park - one of the world''s longest underwater cave systems + Gold Rock Beach","Tiger Beach ~20 mi off West End - tiger/lemon/hammerhead sharks; liveaboards ex-West End","Post-Dorian (2019) recovery well advanced; Port Lucaya active","Freeport flagged urban crime; malaria none; hurricane Jun-Nov peak Aug-Oct (Dorian 2019)"],"safety":{"emergency":"911 / 919","hospital":"Rand Memorial (Freeport); Nassau referral for tertiary (verify post-Dorian)","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct (Dorian 2019 ground-zero)","dive_no_fly":"18-24h (DAN)","firearms_ammo_law":"Bahamas ammo law applies — disclose","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"Tiger Beach","blurb":"\"located 32 km (20 mi) or an hour, by boat, off the coast of the West End of Grand Bahama Island\"; depth \"from 6m (20 ft) to 30m (100 ft)\"; tiger sharks year-round, \"October to January are the best months\"; also nurse, Caribbean reef and lemon sharks; operators \"request for you to have your Open Water certificate with more dives. Some companies will request at least 30 dives logged\"; LiveAboard.com lists Bahamas Aggressor II and Dolphin Dream","si":["liveaboard","diveglobal","wildlife","expedition"],"commission":"affiliate","wells":["activities","move"],"draw_rank":1,"tier_absent_reason":"does-not-compete","source":"https://www.liveaboard.com/diving/bahamas/tiger-beach","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"UNEXSO (Underwater Explorers Society) diving","blurb":"\"Opening its doors in 1965, UNEXSO was one of the first organizations to offer recreational scuba diving in the Bahamas\"; \"known as the most established dive center in The Bahamas\"; ⚠️ \"We will be relaunching our diving program\" - Wreck Dive, Shark Dive and Concierge Diving all marked \"RETURNING SOON!\" on 2026-10-02","si":["diveglobal","wildlife"],"commission":"operator","wells":["activities"],"draw_rank":31,"tier_absent_reason":"does-not-compete","source":"https://www.sanctuarybaybahamas.com/unexso","accessed":"2026-10-02"},{"name":"Lucayan National Park","blurb":"\"this 40-acre National Park\" holds \"one of the largest underwater cave systems in the world, with two caves open to the public. Swimming in the caves is prohibited\"; \"a special permit is required for diving\"; the island page adds nature trails, boardwalks, six ecosystems, mangrove swamp and pine forest","si":["wildlife","hiking","tropical","family"],"wells":["activities"],"draw_rank":2,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/plan-your-trip/things-to-do/lucayan-national-park","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Gold Rock Beach","blurb":"on the East End inside Lucayan National Park; the Ministry of Tourism notes it was \"featured in Pirates of the Caribbean films\"","si":["tropical","romance","family"],"wells":["activities"],"draw_rank":3,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - pair with a beach stay or boat day","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a beach - free; the stay and a boat day are the paid route"},{"name":"Sanctuary Bay, home of The Dolphin Experience","blurb":"UNEXSO''s dolphin site at Sterling Circle, Freeport: \"the dolphins live in ocean enclosures that mirror their natural habitat\"; a \"natural 9-acre lagoon\"; Dolphin Encounter \"$85 (adults) | $50 (children) exc. VAT\", Dolphin Swim \"$219.00 exc. VAT | 2.5 hours\", Glass Bottom Boat Adventure on a \"56 foot glass bottom boat\" \"$65 (adults) $55 (children) exc. VAT | 1.5 hours\"; \"Open 9am-5pm Monday to Saturday\"","si":["family","wildlife","ocean"],"commission":"operator","wells":["activities","move"],"draw_rank":4,"tier_absent_reason":"does-not-compete","source":"https://www.unexso.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Paradise Cove (Deadman''s Reef)","blurb":"\"Snorkeling, Watersports & Activities near Freeport\": snorkel tours, kayak and SUP, freediving and spearfishing courses, the Red Bar and beach front villas; \"*Transportation is provided for all our activities\"; the Ministry calls Deadman''s Reef \"The largest contiguous man-made reef, is perfectly suited for snorkeling\"; \"All booked activities and tours include a non-refundable 7% processing fee\"","si":["tropical","family","diveglobal","adventure"],"commission":"operator","wells":["activities","stay","eat"],"draw_rank":5,"tier_absent_reason":"not-established","source":"https://deadmansreef.com/","accessed":"2026-10-02"},{"name":"Viva Fortuna Beach by Wyndham","blurb":"\"Uncover the sole all-inclusive resort on the island\"; \"274 rooms\" each with \"a balcony or terrace\" in \"Victorian structures\"; \"three a la carte dining venues, a buffet restaurant, beach snack bar, and two full-service bars\"; water sports, paddleboard, pickleball and trapeze lessons; \"perfect for families, couples\"","si":["family","tropical","romance"],"commission":"hotel","wells":["stay","eat","activities"],"draw_rank":6,"tier_absent_reason":"not-established","source":"https://vivaresortsbywyndham.com/resorts/viva-fortuna-beach-by-wyndham-freeport-grand-bahama/","accessed":"2026-10-02"},{"name":"Port Lucaya Marketplace","blurb":"\"the largest shopping, dining and entertainment open air facility in the Bahamas, with over forty specialty stores and boutiques, eleven restaurants ... and eleven bars/lounge\"; \"a 9 1/2 acre waterside open-air facility situated on the Lucayan Strip\"; \"two generously stocked Straw Markets, two Craft Centres\"; \"roughly 12 miles from the Harbour/Cruise Port\"","si":["entertainment","culinary","culture","family"],"wells":["activities","eat","move","shop"],"draw_rank":7,"tier_absent_reason":"not-sold","source":"https://www.portlucaya.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"venue (retail) - non-commissionable; a guided town or shopping tour sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a market, shop or gallery - free to visit; a guided tour is the paid route"},{"name":"Bahamas Aggressor II - Tiger Beach itinerary","blurb":"\"Tiger Beach - departs from Freeport and visits the remote areas around the West End of Grand Bahama and Tiger Beach which is frequented by Caribbean Reef Sharks, Lemon Sharks and Tiger Sharks\"; \"Up to 4 dives per day (night dives not included), averaging 19-22 dives\"; depth \"25 – 130 ft (8m – 40m)\"; \"All dives are from the yacht\"","si":["liveaboard","diveglobal","wildlife"],"commission":"operator","wells":["activities","stay"],"draw_rank":8,"tier_absent_reason":"does-not-compete","source":"https://www.aggressor.com/destination/bahamas","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"East End Lodge","blurb":"\"WORLD CLASS FLY FISHING EXPERIENCE ON GRAND BAHAMA ISLAND\"; packages include \"ALL AIRPORT TRANSFERS\", \"All inclusive meals and accommodations\", \"Daily Guided fishing\", \"Fishing equipment\" and \"all taxes & resort fees\"; \"Same affordable pricing all year round\"","si":["adventure","sports","ocean"],"commission":"operator","wells":["activities","eat","fly","gear","move","stay"],"draw_rank":9,"tier_absent_reason":"not-established","source":"https://eastendlodge.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"h2obonefishing","blurb":"\"WE ARE KNOWN FOR HAVING SOME OF THE LARGEST BONEFISH IN THE WORLD\"; \"average size of bonefish is in the 4+ lb range\"; \"We trailer our boats to make the most of the fishing and the weather\"; publishes a 2027 package rate of $1961 per person double occupancy for 3 nights and 2 days fishing","si":["adventure","sports","ocean"],"commission":"operator","wells":["activities","stay"],"draw_rank":10,"tier_absent_reason":"not-established","source":"https://www.h2obonefishing.com/rates","accessed":"2026-10-02"},{"name":"Peterson Cay National Park","blurb":"\"Located just off the coast of Grand Bahama Island, Peterson Cay is a protected National Park managed by the Bahamas National Trust\"; a 1.5-acre park with snorkelling and diving over four reef zones","si":["tropical","wildlife","diveglobal"],"wells":["activities"],"draw_rank":11,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Garden of the Groves","blurb":"\"Explore winding trails through lush vegetation, cascading waterfalls and sparkling fountains\"; \"the picturesque chapel, which has been consecrated and is a favourite place for weddings\"; the island page gives 12 acres and a Christian labyrinth","si":["romance","family","senior"],"commission":"venue","wells":["activities"],"draw_rank":12,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/plan-your-trip/things-to-do/garden-of-the-groves","accessed":"2026-10-02"},{"name":"Taino Beach","blurb":"\"Popular beach with calm waters, beach bars, and a casual local vibe. Great choice for families and relaxed beach time\"","si":["tropical","family"],"wells":["activities"],"draw_rank":13,"tier_absent_reason":"not-sold","source":"https://nassaubahamascruiseterminal.com/freeport-bahamas","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - pair with a beach stay or boat day","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a beach - free; the stay and a boat day are the paid route"},{"name":"Tony Macaroni''s Conch Experience","blurb":"\"Since 1992, his conch shack has remained on the same spot, overlooking Taino Beach\"; visitors come \"for the conch burgers, the homemade hot sauce, or even the weekly live jazz on the beach\"","si":["culinary","culture","entertainment"],"commission":"venue","wells":["activities","eat"],"draw_rank":14,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/experiences/tony-macaroni-freeport","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"West End","blurb":"the island''s oldest town, 55 nautical miles from Florida, a \"First-rate destination for bonefishing and big game fishing\"; Tiger Beach liveaboards depart from Old Bahama Bay at West End","si":["adventure","sports","culture"],"wells":["activities"],"draw_rank":15,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Celebration Key","blurb":"Carnival Cruise Line''s destination \"at Sharp Rocks, on the eastern coast of Grand Bahama Island\", \"officially opened and inaugurated on July 19, 2025, with the call of Carnival Vista\"; designed for \"two of the world''s largest passenger ships simultaneously\"; Cruise Hive: \"20 miles east of Freeport\"","si":["family","tropical","entertainment"],"commission":"bundle","wells":["activities","move"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://www.cruisemapper.com/ports/celebration-key-bahamas-port-2144?tab=news","accessed":"2026-10-02"},{"name":"Junkanoo","blurb":"the Ministry''s December 2, 2025 release dated the parades Boxing Day, December 26, and New Year''s Day, January 1, 2026: \"Nassau''s parades are the largest and most competitive, but Grand Bahama, Bimini, Eleuthera and Abaco host their own spectacular versions\"","si":["culture","spectator","entertainment","family"],"wells":["activities"],"draw_rank":17,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/pressroom/junkanoo-when-a-bahamian-december-beats-loudest","accessed":"2026-10-02","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Pelican Bay Hotel","blurb":"\"The Happiest Hotel on Grand Bahama Island\" on Sea Horse Road at Port Lucaya; \"Three Pools\"; Sabor Restaurant & Bar on site; \"Book Direct for the Best Rate Guarantee\" from \"$150\"; Port Lucaya Marina cites \"over 185 rooms at the Pelican Bay Resort\"","si":["tropical","romance","family"],"commission":"hotel","wells":["stay","eat"],"draw_rank":18,"tier_absent_reason":"not-established","source":"https://www.pelicanbayhotel.com/","accessed":"2026-10-02"},{"name":"Caribbean Divers","blurb":"the dive shop at Bell Channel Inn: \"1 DIVE $55 2 DIVE $95\" up to \"10 DIVE $310\"; \"LEARN TO SCUBA DIVE $120 CERTIFICATION COURSE $399\"; resort classes \"held daily from 9 a.m. till 12:00 noon\" with \"A 5-10 min. boat ride to the dive site\"; Wreck Dive and Shark Dive specialties; hotel and dive packages by season","si":["diveglobal","adventure"],"commission":"operator","wells":["activities","gear","move","stay"],"draw_rank":19,"tier_absent_reason":"does-not-compete","source":"https://bellchannelinn.com/divingrates.php","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Viva Diving at Viva Fortuna Beach","blurb":"a dive centre inside Viva Fortuna Beach billed as \"The shark capital of the Caribbean\"; 14 mapped sites including Sharks Alley, wrecks and blue holes; 2-dive package $146, shark dive $240, snorkelling from $79, prices exclude 10% VAT; courses from age 8","si":["diveglobal","family"],"commission":"operator","wells":["activities"],"draw_rank":20,"tier_absent_reason":"does-not-compete","source":"https://divewithviva.com/","accessed":"2026-10-02"},{"name":"Rand Nature Centre","blurb":"\"comprises 100 acres of natural beauty in the heart of Freeport\"; \"A 2,000 foot trail winds through through pine barrens, native and exotic coppice\"; \"Peak birdwatching season is from October to May\"; \"Acquired by the BNT in 1992\"","si":["wildlife","hiking","family","senior"],"commission":"venue","wells":["activities"],"draw_rank":21,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/plan-your-trip/things-to-do/rand-memorial-nature-center","accessed":"2026-10-02"},{"name":"Grand Bahama Yacht Club","blurb":"\"Full-Service Marina and Port of Entry\": \"Dockage for vessels up to 200 feet\", \"Customs and immigration clearance\", \"High-speed, triple-filtered fuel\", \"24-hour security\", \"Marina assistance on VHF Channel 16\"; \"Free ferry service for marina guests to Port Lucaya Marketplace and the nearby beach\"","si":["yacht","sailing","motoring"],"commission":"venue","wells":["activities","move","stay"],"draw_rank":22,"tier_absent_reason":"not-established","source":"https://www.grandbahamayachtclub.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bell Channel Inn","blurb":"\"a Beautiful and Budget-Friendly Hotel ideal for the whole family, couples or groups of friends\"; \"Our collection of 32 rooms\" with the \"Upstairs on the Bay\" restaurant and the Caribbean Divers dive shop on site; King''s Road, Freeport","si":["diveglobal","family","group"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":23,"tier_absent_reason":"not-established","source":"https://bellchannelinn.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Upstairs on the Bay","blurb":"\"located off Midshipman Road, Freeport Grand Bahama on the third floor of Bell Channel Inn\"; \"7 Days/A Week - 7:30 AM - 11:00 PM\"; \"American Cuisine & Authentic Bahamian Island style food\" with \"fresh seafood dishes, made with locally-caught seafood\"","si":["culinary","family"],"commission":"venue","wells":["eat","stay"],"draw_rank":24,"tier_absent_reason":"does-not-compete","source":"https://bellchannelinn.com/restaurant.php","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Keith Cooper''s stingray meet-and-greets","blurb":"at West End: \"Hugger, Big Mama, and Dark Chocolate are just a few of the familiar faces that swim up to greet Keith and his guests during his routine meet-and-greets\"","si":["wildlife","ocean","family"],"commission":"guide","wells":["activities"],"draw_rank":25,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/experiences/keith-coopers-stingrays-freeport","accessed":"2026-10-02"},{"name":"Ben''s Cave","blurb":"an inland blue hole in the Lucayan cave system \"accessible only with authorized dive instructor\" per the Ministry of Tourism","si":["diveglobal","expedition","wildlife"],"wells":["activities"],"draw_rank":26,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Owl''s Hole","blurb":"\"Fresh water blue hole hidden in a vast forest of Caribbean pine\", reached by ATV","si":["adventure","wildlife"],"wells":["activities"],"draw_rank":27,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Picasso''s Gallery","blurb":"\"a dive spot famous for its vibrant coral heads in the shape of a painter''s palette\"","si":["diveglobal","ocean"],"wells":["activities"],"draw_rank":28,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/experiences/dive-freeport","accessed":"2026-10-02","commission":"venue (retail) - non-commissionable; a guided town or shopping tour sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a market, shop or gallery - free to visit; a guided tour is the paid route"},{"name":"Daddy Brown''s Conch and Seafood Stand","blurb":"named by Port Lucaya Marketplace \"for authentic Bahamian Island treats\"","si":["culinary","culture"],"commission":"venue","wells":["eat"],"draw_rank":29,"tier_absent_reason":"does-not-compete","source":"https://www.portlucaya.com/","accessed":"2026-10-02"},{"name":"Sabor Restaurant & Bar","blurb":"the on-site restaurant and bar at Pelican Bay Hotel, Port Lucaya","si":["culinary","romance"],"commission":"venue","wells":["eat","stay"],"draw_rank":30,"tier_absent_reason":"does-not-compete","source":"https://www.pelicanbayhotel.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Taino Beach Resort & Clubs","blurb":"a membership resort: \"Unlock the Ultimate Paradise with Taino Beach Resort & Clubs Membership\"; site lists Flamingo Bay Hotel & Marina, watersports, a restaurant and weddings, and Interval International","si":["family","tropical"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":32,"tier_absent_reason":"not-established","source":"https://tainobeach.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Coconut & Fruit Daiquiri Stand","blurb":"\"our famous Coconut & Fruit Daiquiri Stand\" at Port Lucaya Marketplace","si":["culinary","entertainment"],"commission":"venue","wells":["eat"],"draw_rank":33,"tier_absent_reason":"does-not-compete","source":"https://www.portlucaya.com/","accessed":"2026-10-02"}],"faq":[{"q":"What is worth doing in Grand Bahama / Freeport?","a":"Tiger Beach shark liveaboard — multi-day tiger + lemon + hammerhead shark dives.","source":"https://www.liveaboard.com/diving/bahamas/tiger-beach"},{"q":"How do I get to Grand Bahama Island?","a":"By air into Freeport (FPO): the Ministry of Tourism lists American Airlines daily from Miami, Bahamasair from Fort Lauderdale and Raleigh, Sunwing from Toronto and Montreal, and Western Air daily from Nassau and Fort Lauderdale. By sea, Balearia sails Fort Lauderdale to Freeport on Tuesday, Thursday and Saturday; the Bahamas Paradise Cruise service is listed as \"Temporarily Suspended\".","source":"https://www.bahamas.com/getting-here/flying","accessed":"2026-10-02"},{"q":"How do I get from Nassau to Grand Bahama?","a":"The Ministry of Tourism lists Western Air with daily service from Nassau to Freeport. Bahamas Ferries also has a Freeport office (807-8018) and takes reservations on (242) 323-2166 Ext. 250; its homepage did not show a Freeport schedule.","source":"https://www.bahamas.com/getting-here/flying","accessed":"2026-10-02"},{"q":"Can you take a ferry to Grand Bahama?","a":"Yes. The Ministry of Tourism lists \"Balearia: Ft. Lauderdale, FL | Freeport, Grand Bahama | Tu, Th, Sa\". The Bahamas Paradise Cruise service is listed as \"Temporarily Suspended\".","source":"https://www.bahamas.com/getting-here/flying","accessed":"2026-10-02"},{"q":"What is the Grand Bahama airport redevelopment?","a":"The Nassau Guardian reported on June 20, 2025 that the redevelopment \"commenced in March 2024 with demolition of the old terminal\", that the international terminal had been upgraded, and that Dr Kenneth Romer was \"very optimistic that Grand Bahama will see a new airport come 2026.\" No page read on 2026-10-02 confirmed an opening.","source":"https://www.thenassauguardian.com/news/romer-optimistic-that-gb-could-have-new-airport-in-2026/article_58c3a396-cd7c-4aa6-980c-bbc8e731fc1f.html","accessed":"2026-10-02"},{"q":"What is the Grand Bahama Island cruise port?","a":"There are two. Carnival''s Celebration Key, \"at Sharp Rocks, on the eastern coast of Grand Bahama Island\", \"was officially opened and inaugurated on July 19, 2025\". The Port Lucaya Freeport cruise port lies about 20 miles to its west; in February 2024 an $80 million cruise port and water park there was \"slated for completion towards the end of 2026\" (Eyewitness News).","source":"https://www.cruisemapper.com/ports/celebration-key-bahamas-port-2144?tab=news","accessed":"2026-10-02"},{"q":"What are the all-inclusive resorts on Grand Bahama?","a":"Viva Fortuna Beach by Wyndham describes itself as \"the sole all-inclusive resort on the island\", with 274 rooms, three a la carte venues, a buffet and two full-service bars.","source":"https://vivaresortsbywyndham.com/resorts/viva-fortuna-beach-by-wyndham-freeport-grand-bahama/","accessed":"2026-10-02"},{"q":"What can you do on Grand Bahama Island?","a":"The Ministry of Tourism names Lucayan National Park and its underwater caves, Gold Rock Beach, Peterson Cay National Park, the Rand Nature Centre, the Garden of the Groves, Owl''s Hole, Deadman''s Reef for snorkelling, Port Lucaya Marketplace, and West End for \"bonefishing and big game fishing\".","source":"https://www.bahamas.com/islands/grand-bahama-island","accessed":"2026-10-02"},{"q":"What time zone is Grand Bahama in?","a":"\"The Bahamas falls in the Eastern Time Zone, and follows Daylight Saving Time.\"","source":"https://www.bahamas.com/faq","accessed":"2026-10-02"},{"q":"When is Junkanoo in Grand Bahama?","a":"The Ministry of Tourism dates the main parades to Boxing Day, December 26, and New Year''s Day (January 1, 2026 in its December 2025 release), and says Grand Bahama hosts \"their own spectacular versions\". It gives no Grand Bahama venue or time.","source":"https://www.bahamas.com/pressroom/junkanoo-when-a-bahamian-december-beats-loudest","accessed":"2026-10-02"},{"q":"What is there for kids on Grand Bahama Island?","a":"Sanctuary Bay''s Dolphin Encounter is billed \"Great option for all ages!\" ($85 adults, $50 children, excluding VAT), and its Glass Bottom Boat Adventure is \"perfect for all ages\" ($65 adults, $55 children, 1.5 hours).","source":"https://www.unexso.com/","accessed":"2026-10-02"}],"seo":{"meta_title":"Grand Bahama & Freeport: Tiger Beach & UNEXSO","meta_description":"Dive Tiger Beach sharks, hand-feed reef sharks at UNEXSO and explore Lucayan caves from Grand Bahama. When to go and how.","slug":"grand-bahama-freeport-bahamas","primary_keyword":"Tiger Beach shark liveaboard","long_tail":["UNEXSO shark dive Freeport","Lucayan National Park Gold Rock Beach","Grand Bahama diving","Freeport Bahamas excursions","Grand Bahama liveaboard"],"jsonl